function pathParse(d){
  if(!d) return [];
  var groups=d.match(/[MmLlHhVvCcSsQqTtAaZz][^MmLlHhVvCcSsQqTtAaZz]*/g);
  if(!groups) return [];
  var out=[];
  for(var i=0;i<groups.length;i++){
    var g=groups[i], c=g[0];
    var nums=(g.slice(1).match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi)||[]).map(Number);
    out.push({cmd:c, nums:nums});
  }
  return out;
}
function pathToAbsolute(d){
  var cmds=pathParse(d), cx=0, cy=0, sx=0, sy=0, out=[];
  for(var i=0;i<cmds.length;i++){
    var c=cmds[i].cmd, n=cmds[i].nums, res=[c.toUpperCase()];
    if('MmLl'.indexOf(c)>=0){ var x=n[0], y=n[1];
      if(c==='m'){ x+=cx; y+=cy; sx+=n[0]; sy+=n[1]; } else { sx=x; sy=y; }
      res.push(x,y); cx=x; cy=y;
    } else if('Hh'.indexOf(c)>=0){ var xh=n[0]; if(c==='h') xh+=cx; res.push(xh); cx=xh; }
    else if('Vv'.indexOf(c)>=0){ var yv=n[0]; if(c==='v') yv+=cy; res.push(yv); cy=yv; }
    else if('Cc'.indexOf(c)>=0){ var x1=n[0],y1=n[1],x2=n[2],y2=n[3],x=n[4],y=n[5];
      if(c==='c'){ x1+=cx;y1+=cy;x2+=cx;y2+=cy;x+=cx;y+=cy; } res.push(x1,y1,x2,y2,x,y); cx=x;cy=y;
    } else if('Ss'.indexOf(c)>=0){ var sx2=n[0],sy2=n[1],x=n[2],y=n[3];
      if(c==='s'){ sx2+=cx;sy2+=cy;x+=cx;y+=cy; } res.push(sx2,sy2,x,y); cx=x;cy=y;
    } else if('Zz'.indexOf(c)>=0){ res=['Z']; cx=sx;cy=sy; }
    else { res=res.concat(n); }
    out.push(res[0] + res.slice(1).join(' '));
  }
  return out.join(' ');
}
function pathBBox(d){
  var cmds=pathParse(d), cx=0, cy=0, pts=[];
  for(var i=0;i<cmds.length;i++){
    var c=cmds[i].cmd, n=cmds[i].nums;
    if('MmLl'.indexOf(c)>=0){ var x=n[0],y=n[1]; if(c==='m'||c==='l'){x+=cx;y+=cy;} cx=x;cy=y; pts.push([x,y]); }
    else if('Hh'.indexOf(c)>=0){ var xh=n[0]; if(c==='h')xh+=cx; cx=xh; pts.push([cx,cy]); }
    else if('Vv'.indexOf(c)>=0){ var yv=n[0]; if(c==='v')yv+=cy; cy=yv; pts.push([cx,cy]); }
    else if('Cc'.indexOf(c)>=0){ var x=n[4],y=n[5]; if(c==='c'){x+=cx;y+=cy;} cx=x;cy=y; pts.push([x,y]); }
  }
  if(!pts.length) return null;
  var minx=Infinity,miny=Infinity,maxx=-Infinity,maxy=-Infinity;
  for(var j=0;j<pts.length;j++){ minx=Math.min(minx,pts[j][0]); miny=Math.min(miny,pts[j][1]); maxx=Math.max(maxx,pts[j][0]); maxy=Math.max(maxy,pts[j][1]); }
  return {minX:minx,minY:miny,maxX:maxx,maxY:maxy,width:maxx-minx,height:maxy-miny};
}
function pathSimplify(d, prec){
  prec=(prec==null?1:prec); var f=Math.pow(10,prec);
  var cmds=pathParse(d), out=[];
  for(var i=0;i<cmds.length;i++){ var c=cmds[i].cmd, n=cmds[i].nums, r=[c];
    for(var j=0;j<n.length;j++){ r.push(Math.round(n[j]*f)/f); }
    out.push(r[0] + r.slice(1).join(' '));
  }
  return out.join(' ');
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { pathParse:pathParse, pathToAbsolute:pathToAbsolute, pathBBox:pathBBox, pathSimplify:pathSimplify }; }
